// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	cookieLines := []string{in.String}
	logLines := caddyhttp.LoggableCookieHeader(cookieLines)
	if len(logLines) == 0 {
		logLines = caddyhttp.LoggableStringArray(cookieLines)
	}

	headerValues := make([]string, 0, len(logLines))
	for _, line := range logLines {
		if line == "" {
			headerValues = append(headerValues, line)
			continue
		}
		headerValues = append(headerValues, line)
	}
	if len(headerValues) == 0 {
		headerValues = append(headerValues, in.String)
	}

	originHeader := make(http.Header)
	for i, line := range headerValues {
		if i == 0 {
			originHeader["Cookie"] = []string{line}
			continue
		}
		originHeader["Cookie"] = append(originHeader["Cookie"], line)
	}
	if _, exists := originHeader["Cookie"]; !exists {
		originHeader["Cookie"] = []string{in.String}
	}

	credentialHeader := false
	for key := range originHeader {
		lower := strings.ToLower(key)
		if lower == "cookie" {
			credentialHeader = true
			continue
		}
		if strings.Contains("|set-cookie|authorization|proxy-authorization|", "|"+lower+"|") {
			continue
		}
	}
	if !credentialHeader {
		originHeader["Cookie"] = []string{in.String}
	}

	invalidName := [256]bool{}
	for b := 0; b < 0x21; b++ {
		invalidName[b] = true
	}
	for b := 0x7f; b <= 0xff; b++ {
		invalidName[b] = true
	}
	invalidName['('] = true
	invalidName[')'] = true
	invalidName['<'] = true
	invalidName['>'] = true
	invalidName['@'] = true
	invalidName[','] = true
	invalidName[';'] = true
	invalidName[':'] = true
	invalidName['\\'] = true
	invalidName['"'] = true
	invalidName['/'] = true
	invalidName['['] = true
	invalidName[']'] = true
	invalidName['?'] = true
	invalidName['='] = true
	invalidName['{'] = true
	invalidName['}'] = true

	invalidValue := [256]bool{}
	for b := 0; b < 0x20; b++ {
		invalidValue[b] = true
	}
	invalidValue[0x7f] = true
	invalidValue['"'] = true
	invalidValue[';'] = true
	invalidValue['\\'] = true

	whitespace := [256]bool{}
	whitespace[' '] = true
	whitespace['\t'] = true
	whitespace['\r'] = true
	whitespace['\n'] = true

	originRequest := http.Request{Header: originHeader}
	stdlibCookies := originRequest.Cookies()
	parsedCookies := make([]*http.Cookie, 0, len(stdlibCookies)+len(originHeader["Cookie"]))

	for lineIdx := 0; lineIdx < len(originHeader["Cookie"]); lineIdx++ {
		line := originHeader["Cookie"][lineIdx]
		if len(line) == 0 {
			continue
		}
		rest := line
		for len(rest) > 0 {
			sep := -1
			for si := 0; si < len(rest); si++ {
				if rest[si] == ';' {
					sep = si
					break
				}
			}
			part := rest
			if sep >= 0 {
				part = rest[:sep]
				rest = rest[sep+1:]
			} else {
				rest = ""
			}
			start := 0
			end := len(part)
			for start < end {
				if !whitespace[part[start]] {
					break
				}
				start++
			}
			for end > start {
				if !whitespace[part[end-1]] {
					break
				}
				end--
			}
			if start >= end {
				continue
			}
			part = part[start:end]
			eq := -1
			for ei := 0; ei < len(part); ei++ {
				if part[ei] == '=' {
					eq = ei
					break
				}
			}
			name := part
			val := ""
			if eq >= 0 {
				name = part[:eq]
				val = part[eq+1:]
			}
			if len(name) == 0 {
				continue
			}
			nameOK := true
			for ni := 0; ni < len(name); ni++ {
				ch := name[ni]
				if invalidName[ch] {
					nameOK = false
					break
				}
			}
			if !nameOK {
				continue
			}
			workVal := val
			if len(workVal) >= 2 && workVal[0] == '"' && workVal[len(workVal)-1] == '"' {
				quoted := workVal[1 : len(workVal)-1]
				quotedOK := true
				escaped := false
				for qi := 0; qi < len(quoted); qi++ {
					qb := quoted[qi]
					if escaped {
						if invalidValue[qb] {
							if qb != '"' {
								if qb != '\\' {
									quotedOK = false
									break
								}
							}
						}
						escaped = false
						continue
					}
					if qb == '\\' {
						escaped = true
						continue
					}
					if invalidValue[qb] {
						quotedOK = false
						break
					}
				}
				if quotedOK {
					if !escaped {
						workVal = quoted
					}
				}
			}
			valueOK := true
			for vi := 0; vi < len(workVal); vi++ {
				b := workVal[vi]
				if invalidValue[b] {
					valueOK = false
					break
				}
			}
			if !valueOK {
				continue
			}
			parsedCookies = append(parsedCookies, &http.Cookie{Name: name, Value: workVal})
		}
	}

	cookies := stdlibCookies
	if len(parsedCookies) == len(stdlibCookies) {
		same := true
		for i := 0; i < len(parsedCookies); i++ {
			parsed := parsedCookies[i]
			std := stdlibCookies[i]
			if parsed == nil || std == nil {
				same = false
				break
			}
			if parsed.Name != std.Name {
				same = false
				break
			}
			if parsed.Value != std.Value {
				same = false
				break
			}
		}
		if same {
			cookies = parsedCookies
		}
	}

	actionByName := make(map[string][]cookieFilterAction, len(m.Actions))
	for _, action := range m.Actions {
		if action.Name == "" {
			continue
		}
		if err := action.Type.IsValid(); err != nil {
			continue
		}
		actionByName[action.Name] = append(actionByName[action.Name], action)
	}

	transformedHeader := make(http.Header)
	transformedRequest := http.Request{Header: transformedHeader}

OUTER:
	for ci := 0; ci < len(cookies); ci++ {
		c := cookies[ci]
		if c == nil {
			continue
		}
		cookieName := c.Name
		cookieValue := c.Value
		if cookieName == "" {
			if cookieValue == "" {
				continue
			}
		}

		matchedActions, hasActions := actionByName[cookieName]
		if !hasActions {
			for _, action := range m.Actions {
				if action.Name != cookieName {
					continue
				}
				matchedActions = append(matchedActions, action)
				hasActions = true
				break
			}
		}
		if !hasActions {
			encoded := cookieName + "=" + cookieValue
			existing := transformedRequest.Header.Get("Cookie")
			if existing != "" {
				transformedRequest.Header.Set("Cookie", existing+"; "+encoded)
			} else {
				transformedRequest.Header.Set("Cookie", encoded)
			}
			continue
		}

		applied := false
		for ai := 0; ai < len(matchedActions); ai++ {
			action := matchedActions[ai]
			if action.Name != cookieName {
				continue
			}
			if err := action.Type.IsValid(); err != nil {
				continue
			}
			switch action.Type {
			case replaceAction:
				c.Value = action.Value
				encoded := cookieName + "=" + c.Value
				existing := transformedRequest.Header.Get("Cookie")
				if existing != "" {
					transformedRequest.Header.Set("Cookie", existing+"; "+encoded)
				} else {
					transformedRequest.Header.Set("Cookie", encoded)
				}
				applied = true
				continue OUTER
			case hashAction:
				src := cookieValue
				digest := sha256.Sum256([]byte(src))
				hexdigits := "0123456789abcdef"
				hashed := make([]byte, 8)
				for hi := 0; hi < 4; hi++ {
					hashed[hi*2] = hexdigits[digest[hi]>>4]
					hashed[hi*2+1] = hexdigits[digest[hi]&0x0f]
				}
				c.Value = string(hashed)
				encoded := cookieName + "=" + c.Value
				existing := transformedRequest.Header.Get("Cookie")
				if existing != "" {
					transformedRequest.Header.Set("Cookie", existing+"; "+encoded)
				} else {
					transformedRequest.Header.Set("Cookie", encoded)
				}
				applied = true
				continue OUTER
			case deleteAction:
				applied = true
				continue OUTER
			}
		}

		if !applied {
			encoded := cookieName + "=" + cookieValue
			existing := transformedRequest.Header.Get("Cookie")
			if existing != "" {
				transformedRequest.Header.Set("Cookie", existing+"; "+encoded)
			} else {
				transformedRequest.Header.Set("Cookie", encoded)
			}
		}
	}

	in.String = transformedRequest.Header.Get("Cookie")
	return in
}

